 options=[dict(id=f'o{i+1}',text=x[0])for i,x in enumerate(opts)];explain={f'o{i+1}':x[1]for i,x in enumerate(opts)}
 # Deterministic rotation avoids authoring-position clues while preserving option IDs.
 shift=int(hashlib.sha256(qid.encode()).hexdigest()[:4],16)%len(options);options=options[shift:]+options[:shift]
 pset=list(dict.fromkeys([page,*pages]))
