 entry=dict(id=qid,version=1,status='draft',authorId=AUTHOR,stem=stem,selectionMode='multi'if len(correct)>1 else 'single',type=kind,difficulty=difficulty,cognitiveSkill='numerical'if kind=='numerical'else 'algorithm'if kind=='algorithm_trace'else 'recall'if kind=='definition'else 'application'if kind in ('diagram','scenario')else 'conceptual',week=1,lectureId='L03',topic='Mathematical Background',subtopic=C[cs[0]]['subtopic'],tags=['mathematics',C[cs[0]]['subtopic']],conceptIds=cs,assumptions=list(assumptions),options=options,correctOptionIds=[f'o{i+1}'for i in correct],citations=citations,solution=dict(justification=why,optionExplanations=explain,steps=list(steps),formulas=list(formulas),simpleExplanation=simple or why,memoryAid=memory,misconceptions=[trap]if trap else [],examTraps=[trap]if trap else [],prerequisiteConceptIds=[]),origin='generated',reviewIds=[])
 Q.append(entry)
