question(c,'If A(t)=[[t²,sin t],[3,2t]], what is A_dot at t=0?', [('[[0,1],[0,2]]','The derivatives are[[2t,cos t],[0,2]], evaluated at0.'),('[[0,0],[3,0]]','This isA(0), not its derivative.'),('[[2,1],[3,2]]','The derivative of3 is0 and2t evaluates to0 at t=0.'),('[[0,0],[1,2]]','This exchanges derivative entries as if a transpose were required.')],'Matrix differentiation is entrywise; it neither transposes the array nor preserves constant entries.',kind='numerical',steps=['Differentiate each entry: A_dot=[[2t,cos t],[0,2]].','At t=0 usecos0=1, obtaining[[0,1],[0,2]].'],formulas=[form('A_dot=[d a_ij/dt]',{'A':'time-varying matrix','a_ij':'individual entry','t':'time'})],assumptions=['Angles are in radians.'])
c=concept(104,'Rotation derivative convention','The stated spatial-angular-velocity convention left-multiplies R by S(omega).')
question(c,'Using the lecture convention R_dot=S(omega)R, what is R_dot when R=I and omega=(0,0,2)^T?', [('[[0,−2,0],[2,0,0],[0,0,0]]','Multiplying the displayedS byI preservesS.'),('The identity matrix','The derivative depends on angular velocity, not simply onR beingI at that instant.'),('The zero matrix','Zero derivative would require zero angular velocity here.'),('[[0,2,0],[−2,0,0],[0,0,0]]','This reverses the specified skew-matrix signs.')],'At the identity orientation, the instantaneous derivative is precisely the angular-velocity skew matrix.',pages=[100],kind='numerical',steps=['FormS from omega: [[0,−2,0],[2,0,0],[0,0,0]].','UseR_dot=SI=S.'],formulas=[form('R_dot=S(omega)R',{'R':'rotation matrix','omega':'spatial angular velocity','S':'skew matrix'},{'omega':'rad/s','R_dot':'1/s'},['Use the left-multiplication convention stated by the slide.'])],assumptions=['Use the slide convention R_dot=S(omega)R, with omega represented in the corresponding spatial frame.'])
# p105–108: probability foundations and distributions.
c=concept(105,'Probability normalization','Discrete exhaustive outcome probabilities are nonnegative and sum to1.')
question(c,'Which list can be a PMF over four exhaustive mutually exclusive outcomes?', [('(0.1,0.2,0.3,0.4)','All entries are nonnegative and sum to1.'),('(0.2,0.2,0.2,0.2)','The total is0.8, leaving missing probability mass.'),('(−0.1,0.3,0.4,0.4)','The total is1 but a probability cannot be negative.'),('(0.4,0.4,0.4,0.4)','The total is1.6, exceeding1.')],'Both requirements matter: acceptable individual values do not excuse a wrong total, and a correct total does not excuse negative entries.',pages=[107],kind='numerical',steps=['Check each entry lies in[0,1].','Sum each candidate; only0.1+0.2+0.3+0.4=1 passes both checks.'],formulas=[form('sum_i P(X=x_i)=1',{'x_i':'exhaustive mutually exclusive discrete outcomes'})])
c=concept(105,'Experiment and sample space','Trials generate observations; discrete/continuous spaces distinguish countable from uncountable outcomes.')
question(c,'Which pairing follows the lecture distinction between sample spaces?', [('A count of successful grasps is discrete; an ideal real-valued wall distance is continuous','The count takes countably many values; the ideal distance can vary over an interval.'),('Both must be continuous because robots move','The physical system does not determine whether the recorded outcome is a count or a real value.'),('Both must be discrete because a computer is involved','The question asks about mathematical models, not storage precision.'),('An experiment is the probability assigned to an outcome','The slide defines an experiment as an observation process, not a probability value.')],'Choose the sample-space type from the modeled outcomes.',kind='scenario',assumptions=['Wall distance is modeled as an ideal real variable, before digitization.'])
c=concept(105,'Available-state probability diagram','The diagram depicts four available neighboring states each with probability0.25, excluding blocked states.')
question(c,'In printed slide11, each of the four available states is labeled0.25. Under that depicted distribution, what is the probability of selecting one of any two distinct available states?', [('0.50','The two mutually exclusive state probabilities add:0.25+0.25.'),('0.25','This is the probability of one available state, not two.'),('0.0625','Multiplying0.25×0.25 would describe an intersection under an independence assumption, not a one-choice union.'),('1.00','That is the total probability over all four states.')],'A single choice can land in either of two disjoint states, so add their masses.',kind='diagram',steps=['Each selected state has mass0.25.','For disjoint alternatives, total mass=0.25+0.25=0.50.'],assumptions=['Exactly one of the four depicted available states is selected; the four labels form the complete depicted distribution.'])
c=concept(106,'Bayes rule and conditional reversal','Posterior equals likelihood times prior divided by positive evidence; reversing conditioning changes meaning.')
question(c,'P(A)=0.2, P(B|A)=0.8 and P(B)=0.4. What is P(A|B)?', [('0.4','Bayes gives0.8×0.2/0.4=0.4.'),('0.8','This copiesP(B|A), reversing the conditioning.'),('0.16','This is the numeratorP(B|A)P(A), before normalization.'),('0.1','This divides the prior by the wrong combination of terms.')],'The evidence term normalizes the likelihood-weighted prior.',kind='numerical',steps=['P(A|B)=P(B|A)P(A)/P(B).','Compute0.8×0.2=0.16.','Normalize0.16/0.4=0.4.'],formulas=[form('P(A|B)=P(B|A)P(A)/P(B)',{'A,B':'events'},assumptions=['P(B)>0'])],trap='TreatingP(A|B) andP(B|A) as interchangeable.')
question(c,'For the displayed Bayes formula, which condition is necessary to divide by P(B)?', [('P(B)>0','Conditioning by this elementary formula requires positive evidence probability.'),('P(B)=0','That would produce division by zero.'),('P(A)=P(B)','Equal event probabilities are not required.'),('A and B must be independent','Bayes rule is useful precisely when they may be dependent.')],'The denominator must be nonzero; independence is not a prerequisite.',difficulty='medium')
c=concept(106,'Prior, posterior and localization','Belief before evidence differs from robot-state belief conditioned on sensor data.')
question(c,'A robot updates its state estimate after observing noisy sensor data z. Which quantity is its posterior state belief?', [('P(x|z)','This conditions the robot statex on the observationz.'),('P(z|x)','This is a measurement likelihood given a hypothesized state.'),('P(x)','This is the prior before incorporatingz.'),('P(z)','This is the marginal probability of the observation.')],'State given observation is the posterior; observation given state is the likelihood.',kind='scenario',memory='Posterior asks: which state, given what I saw?')
c=concept(106,'Bayesian speech decoding','Observed audio is evidence; candidate word sequence receives likelihood times prior.')
question(c,'For a fixed observed audio signal o, which score ranks candidate word sequences i by the stated posterior?', [('P(o|i)P(i)','P(o) is the same positive normalization for every candidate.'),('P(i|o)P(o|i)P(i)','This multiplies the posterior by its evidence factors again.'),('P(o) alone','It is constant across candidate word sequences and cannot rank them.'),('P(i)/P(o|i)','This divides by rather than weights by the likelihood.')],'Compare how well each sequence explains the audio and how plausible that sequence was beforehand.',kind='scenario',assumptions=['The observed audioo is fixed andP(o)>0.'])
c=concept(107,'Random variable definition','A random variable maps experimental outcomes to real numerical values.')
question(c,'Which object is a random variable under X:Omega→R?', [('A function assigning a numerical reward to each possible trial outcome','It maps outcomes to real numbers as specified.'),('Only the set of all outcomes Omega','That set is the function domain, not the function itself.'),('Only one observed reward value','One realization is not the entire mapping.'),('A function that must assign equal probabilities to all outcomes','The definition imposes no uniform-probability requirement.')],'The random variable translates a trial outcome into a number; its realized value is only one output.',kind='definition',difficulty='easy')
c=concept(107,'Expected value and reward','Expectation averages numerical outcomes weighted by their probabilities.')
question(c,'An action yields reward10 with probability0.3 and reward−2 with probability0.7. What is its expected reward?', [('1.6','0.3×10+0.7×(−2)=3−1.4=1.6.'),('4','This is the unweighted mean of10 and−2.'),('8','This sums rewards without probability weights.'),('4.4','This incorrectly treats the negative reward as positive.')],'A likely penalty counts more heavily than an unlikely outcome of the same size.',kind='numerical',steps=['E(R)=sum_r rP(R=r).','E(R)=10(0.3)+(−2)(0.7)=1.6.'],formulas=[form('E(R)=sum_r rP(R=r)',{'R':'reward random variable'},{'R,E(R)':'reward units'})],trap='An expected value need not itself be one of the possible observed rewards.')
c=concept(107,'PMF versus PDF and continuous expectation','Discrete expectation is a sum of masses; continuous expectation integrates values against density.')
question(c,'Which expression is the mean of a continuous variable with density f_X?', [('Integral over realx of x f_X(x) dx','The slide weights each continuous value by its density and integrates.'),('Integral over realx of f_X(x) dx','For a normalized PDF this is1, not the mean.'),('The largest value of f_X(x)','A peak density is not a mean.'),('Sum of all valuesx without probability weighting','This ignores the probability law and is not the displayed expectation.')],'The factorx changes normalization into an average value.',kind='definition',formulas=[form('E(X)=integral_{-infinity}^{infinity} x f_X(x) dx',{'X':'continuous random variable','f_X':'density'})])
question(c,'A continuous density is f(x)=2x for0≤x≤1 and0 elsewhere. What is E(X)?', [('2/3','Integrate x×2x:2[x³/3]_0^1=2/3.'),('1','Integral of the density alone equals1, not the mean.'),('1/2','That is the mean of a uniform distribution, not this increasing density.'),('2','The maximum density value is not the mean.')],'Greater density near1 shifts the mean above the midpoint.',kind='numerical',steps=['E(X)=integral_0^1 x(2x)dx.','Integrate2x² to(2/3)x³.','Evaluate between0 and1 to obtain2/3.'],formulas=[form('E(X)=integral x f_X(x) dx',{'X':'continuous variable','f_X':'specified density'})],assumptions=['Use the density exactly as specified; the integral exists.'])
c=concept(108,'Binomial model assumptions and applications','Independent two-outcome trials with fixed success probability support the binomial success count.')
question(c,'Which model matches the lecture NLP binomial example?', [('Count sentences containing a transitive verb over independent yes/no trials with a common success probability','This supplies the Bernoulli trials and fixedp in the displayed formula.'),('Measure each sentence duration as an arbitrary real number','That is not a count of binary successes.'),('Allow arbitrary dependence but use the same binomial formula without change','The slide explicitly requires independent trials.'),('Count successes while changingp arbitrarily between trials and assume the same simple formula','The displayed binomial expression uses one commonp.')],'The two outcomes define each trial; the count over fixed independent trials is the binomial variable.',kind='scenario',assumptions=['The elementary binomial model assumes fixed trial countn and common success probabilityp.'])
question(c,'A gripper succeeds independently with probability0.8 on each of3 trials. What is the probability of exactly2 successes?', [('0.384','C(3,2)×0.8²×0.2=3×0.64×0.2.'),('0.128','This counts only one ordering of two successes and one failure.'),('0.512','This is the probability of three successes.'),('0.896','This is the probability of at least two successes, not exactly two.')],'The combination factor counts the three positions where the single failure could occur.',kind='numerical',steps=['n=3,r=2,p=0.8.','C(3,2)=3.','P(R=2)=3(0.8)²(0.2)=0.384.'],formulas=[form('P(R=r)=C(n,r)p^r(1-p)^(n-r)',{'n':'trial count','r':'success count','p':'common success probability'},assumptions=['Trials are independent.'])])
c=concept(108,'Gaussian parameters and density','The Gaussian is continuous and characterized by mean and standard deviation; peak depends inversely on spread.')
question(c,'For a univariate Gaussian with mean mu and positive standard deviation sigma, what is its density at x=mu?', [('1/(sigma sqrt(2pi))','The exponent becomes0 and exp(0)=1.'),('0','The Gaussian has its positive maximum density at its mean.'),('sigma sqrt(2pi)','This inverts the normalization factor incorrectly.'),('mu','The mean is a location parameter, not the density height.')],'At the center, only the normalization factor remains.',kind='numerical',steps=['Setx=mu so(x−mu)²=0.','The exponential factor becomes1.','The density is1/(sigma sqrt(2pi)).'],formulas=[form('f(x)=exp(-(x-mu)^2/(2sigma^2))/(sigma sqrt(2pi))',{'mu':'mean','sigma':'positive standard deviation','x':'value'},assumptions=['sigma>0'])],trap='A probability density value is not itself the probability of one exact continuous outcome.')
question(c,'Keeping mu fixed, what happens to the Gaussian peak density when sigma doubles?', [('It halves','At the mean the peak is inversely proportional tosigma.'),('It doubles','This reverses the normalization dependence.'),('It remains unchanged','The peak factor explicitly containssigma.'),('The mean shifts by a factor2','Changing spread alone does not change the location parameter.')],'Spreading the same total density mass over a broader bell lowers its peak.',difficulty='medium',steps=['Old peak=1/(sigma sqrt(2pi)).','New peak=1/(2sigma sqrt(2pi))=half the old peak.'])
c=concept(108,'Process and measurement noise','The slide assigns zero-mean Gaussian models v~N(0,V) and w~N(0,W) in Kalman filtering/SLAM.')
question(c,'Which pairing reproduces the slide’s Kalman-filter noise notation?', [('Process noisev~N(0,V); measurement noisew~N(0,W)','This matches the two displayed roles and symbols.'),('Process noisew~N(V,0); measurement noisev~N(W,0)','It swaps roles and movesV/W into the mean position.'),('Both noises must have nonzero mean1','The displayed mean in both models is0.'),('The binomial count is used for both noises on this slide','The stated SLAM example appears under Gaussian distributions.')],'Do not exchange the process model’s uncertainty with the sensor-measurement uncertainty.',kind='definition',difficulty='easy')
# p109–111: statistical inference and information.
c=concept(109,'MLE versus MAP','MLE maximizes data likelihood; MAP maximizes posterior using a prior.')
question(c,'Two models have likelihoods L1=0.6,L2=0.5 and priors P1=0.2,P2=0.8 for fixed observed data. Which choices follow?', [('MLE chooses model1; MAP chooses model2','Likelihood0.6>0.5, but weighted scores0.12<0.40.'),('Both choose model1','MAP must account for the unequal priors.'),('Both choose model2','MLE does not multiply by the prior.'),('MLE chooses model2; MAP chooses model1','Both comparisons are reversed.')],'The most likely data-fit and the most probable model after using prior knowledge can differ.',kind='numerical',steps=['MLE compares0.6 and0.5, choosingmodel1.','MAP compares0.6×0.2=0.12 with0.5×0.8=0.40.','The shared positive evidence denominator does not change the ordering, soMAP choosesmodel2.'],formulas=[form('theta_MAP=argmax_theta P(data|theta)P(theta)',{'theta':'candidate model','data':'fixed observation'},assumptions=['Evidence is positive and common across candidates.'])],trap='Confusing the parameter selected byargmax with the numerical posterior probability.')
question(c,'If all candidate models have the same positive prior probability and the likelihood has a unique maximizer, how do MLE and MAP compare?', [('They select the same model','Multiplying every likelihood by the same positive constant leaves its ordering unchanged.'),('MAP must select a different model','A prior affects ordering only when its relative values differ.'),('MLE becomes undefined','Likelihood maximization is still defined.'),('MAP ignores the likelihood completely','The posterior still includes the likelihood factor.')],'A uniform prior adds no preference among the candidates.',difficulty='hard',assumptions=['Finite candidate set, equal positive priors, fixed data with positive evidence, and unique likelihood maximum.'])
c=concept(109,'Bayesian factor meanings','Distinguish posterior, likelihood, prior and evidence; MAP selects a model rather than a probability value.')
question(c,'In P(mu_m|s)=P(s|mu_m)P(mu_m)/P(s), which term is the evidence?', [('P(s)','It is the total probability of the observed data across possible models.'),('P(mu_m|s)','This is the posterior model probability.'),('P(s|mu_m)','This is the likelihood conditional on a particular model.'),('P(mu_m)','This is the prior model probability.')],'Evidence normalizes likelihood-weighted prior mass into a posterior distribution.',kind='definition',difficulty='easy')
c=concept(110,'Sequential Bayesian update','The posterior after an observation becomes the prior for the next update.')
question(c,'After processing observationz1, what belief is reused before processingz2 in the described sequential update?', [('The posterior afterz1','The slide explicitly says the updated belief becomes the new prior.'),('The untouched initial prior every time','This discards information fromz1 rather than accumulating it.'),('Only the probability ofz1','An observation probability is not the full updated state belief.'),('A uniform distribution regardless of the observation','The described procedure does not reset beliefs to uniform.')],'Bayesian updating carries accumulated evidence forward.',kind='sequence',difficulty='easy')
question(c,'Which wall-distance estimator uses the extra information associated with MAP in the lecture example?', [('One combining new range data with prior map knowledge','That combination is the stated contrast with data-only estimation.'),('One using sensor data but no prior model information','This reflects the example’s MLE side.'),('One ignoring both sensor readings and the map','That is not estimation from either source.'),('One assuming extra data guarantees zero error','The example offers no such exact finite-data guarantee.')],'Prior knowledge contributes another source of information; it does not magically remove all noise.',kind='scenario',trap='Treating the slide’s qualitative accuracy statement as an unconditional guarantee under biased sensors or a wrong model.')
c=concept(111,'Entropy and uncertainty','Entropy is the probability-weighted average information; base2 gives bits and measures class impurity.')
question(c,'A binary class is equally likely to be fragile or sturdy. What is its entropy using log base2?', [('1 bit','−2×0.5log2(0.5)=1.'),('0 bits','Zero would correspond to certainty, not an equal split.'),('0.5 bits','This counts only one of the two equal contributions.'),('2 bits','Two outcomes do not imply2bits; log2(2)=1.')],'One fair binary uncertainty carries one bit of information.',kind='numerical',steps=['Each probability is0.5 andlog2(0.5)=−1.','H=−[0.5(−1)+0.5(−1)]=1bit.'],formulas=[form('H(X)=-sum_x p(x)log_2 p(x)',{'p(x)':'class probability'},{'H':'bits'})])
question(c,'Which distribution has lower entropy: a certain class(1,0) or an equal binary mixture(0.5,0.5)?', [('The certain class has0 bits, versus1 bit for the equal mixture','Certainty removes class uncertainty.'),('The certain class has1 bit, versus0 for the mixture','This reverses uncertainty and entropy.'),('They both have1 bit because there are two named classes','A zero-probability class contributes no uncertainty.'),('Entropy is negative for the certain class','Discrete Shannon entropy is not negative here.')],'Entropy depends on probability balance, not just the number of class labels written down.',kind='numerical',steps=['Use the convention0log2(0)=0.','H(1,0)=−1log2(1)=0.','H(0.5,0.5)=1.'],assumptions=['Use0log2(0)=0 by the limiting convention.'],trap='Equating confident predictions with correct predictions; low entropy alone is not proof of model accuracy.')
question(c,'In a classification decision tree, entropy is used primarily to measure what?', [('Class impurity at a node or after a split','The lecture links entropy to uncertainty over class labels.'),('Robot joint torque in newton-metres','Torque is a mechanical quantity, not the information measure here.'),('The number of physical links in an arm','Link count is not entropy.'),('A guarantee that the trained model is correct','Entropy measures uncertainty, not truth of predictions.')],'More mixed class probabilities mean more uncertainty for the tree to reduce.',kind='definition',difficulty='easy')
# p112: state-space form and dynamics.
c=concept(112,'State-space variables and equations','State evolves by first-order equations; input enters throughB and output throughC in the displayed no-feedthrough model.')
question(c,'In x_dot=Ax+Bu and y=Cx, which matrix maps inputu into the state derivative?', [('B','The termBu is the input contribution to x_dot.'),('C','C maps the state to the measured output in this model.'),('A','A maps the current state into its autonomous contribution to x_dot.'),('The state vectorx','x is a variable, not the input mapping matrix.')],'The two equations distinguish state evolution from observation of the state.',kind='definition',difficulty='easy',assumptions=['Use exactly the displayed no-direct-feedthrough output model y=Cx.'])
question(c,'For A=[[0,1],[−2,−3]], B=(0,1)^T, x=(1,2)^T and u=4, what is x_dot?', [('(2,−4)^T','Ax=(2,−8)^T andBu=(0,4)^T, summing to(2,−4).'),('(2,−8)^T','This omits the input contributionBu.'),('(4,−2)^T','This does not follow the specified matrix multiplication.'),('(0,4)^T','This includes only the input and omitsAx.')],'State derivative combines the present-state dynamics and the applied input.',kind='numerical',steps=['Ax=(0×1+1×2,−2×1−3×2)^T=(2,−8)^T.','Bu=(0,4)^T.','x_dot=Ax+Bu=(2,−4)^T.'],formulas=[form('x_dot=Ax+Bu',{'x':'state','u':'input','A':'state matrix','B':'input matrix'})])
question(c,'If C=[1,0] and x=(position,velocity)^T, what does y=Cx report?', [('Position only','The row vector selects the first state component.'),('Velocity only','That would requireC=[0,1].'),('Position plus velocity','That would requireC=[1,1].'),('The derivative of position minus velocity','The output equation performs state selection, not differentiation.')],'The output matrix can select which part of the state is observed.',kind='scenario',difficulty='easy')
c=concept(112,'Higher-order to first-order conversion','Position and velocity can be separate states for a second-order mechanical model.')
question(c,'Given q_ddot+3q_dot+2q=u, choose x1=q and x2=q_dot. Which first-order pair is equivalent?', [('x1_dot=x2; x2_dot=−2x1−3x2+u','The first equation defines velocity; the second rearranges the given dynamics.'),('x1_dot=x1; x2_dot=−2x1−3x2+u','The first derivative ofq isq_dot=x2, notq=x1.'),('x1_dot=x2; x2_dot=2x1+3x2+u','Moving restoring and damping terms to the right gives negative signs.'),('x1_dot=u; x2_dot=x1','This discards the given second-order relationship.')],'Introducing a velocity state lowers equation order without removing the dynamics.',kind='numerical',difficulty='hard',steps=['x1_dot=q_dot=x2.','x2_dot=q_ddot=u−3q_dot−2q.','Substituteq=x1 andq_dot=x2.'],formulas=[form('x=(q,q_dot)^T',{'q':'position','q_dot':'velocity','x':'state vector'})],assumptions=['The second-order equation and state definitions are stipulated in the question.'])
# p113–114: graph structure and a faithful source-figure application.
c=concept(113,'Graph nodes, edges and direction','G=(V,E) distinguishes objects from connections; directed edges allow one-way traversal.')
question(c,'For a factory-floor graph G=(V,E), which interpretation matches the course?', [('V contains docking stations; E contains traversable passages','This maps objects to nodes and connections to edges.'),('V contains only edge costs and E contains docking stations','This reverses nodes and edges.'),('A directed passage must be usable in both directions','Directed edges may encode one-way traversal.'),('A graph must contain no cycles','Acyclicity is a special restriction, not a requirement for every graph.')],'A graph separates locations from permitted movement between them.',pages=[114],kind='scenario',difficulty='easy')
c=concept(113,'Path, cycle and rooted-tree convention','A cycle returns to the start; the lecture uses a rooted acyclic directed-tree convention.')
question(c,'Which sequence is a cycle under the definition given on printed slide19, assuming all listed edges exist?', [('A→B→C→A','It starts and ends atA.'),('A→B→C','Its endC differs from its startA.'),('A alone, with no edge traversed','No sequence of traversed edges is supplied here.'),('Three disconnected verticesA,B,C','There is no connected path between the listed vertices.')],'The defining feature in the slide is return to the starting node along a path.',difficulty='easy',assumptions=['Use a nonempty cycle with at least one traversed edge.'])
question(c,'Under the rooted directed-tree convention used in this lecture, which feature is ruled out?', [('A directed cycle','The slide explicitly requires the tree to contain no cycles.'),('A root node','A root is part of the convention being used.'),('Connections between nodes','A tree remains a connected graph.'),('More than one node','The slide does not limit a tree to a single node.')],'The question uses the lecture’s rooted-tree convention, not a claim that every mathematical tree must be directed.',difficulty='medium',assumptions=['Use the specific rooted, directed convention of printed slide19.'],trap='General graph theory also uses undirected trees; do not universalize the lecture wording.')
c=concept(113,'Weighted path cost','Total traversal cost adds the weights of the traversed edges.')
question(c,'A valid robot path traverses edges with costs4,1,3 and1. What is its total cost?', [('9','Path cost is the sum4+1+3+1.'),('4','This is the number of edges, not their total weighted cost.'),('12','This multiplies some weights instead of summing all of them.'),('1','This reports a minimum individual edge rather than the total.')],'Fewest edges and least total weight are different criteria.',kind='numerical',steps=['Add the four edge weights.','4+1+3+1=9.'],formulas=[form('cost(path)=sum_{e in path} w(e)',{'w(e)':'edge cost','path':'ordered traversed edges'},{'cost,w':'common cost units'})])
c=concept(114,'Factory-floor route diagram','Interpret start/goal, blocked passage and the minimum-cost route1–3–5–6.')
question(c,'In the factory-floor diagram, what is the cost of the green route Dock1→Dock3→Dock5→Dock6?', [('6','The displayed weights are2,3 and1, totaling6.'),('3','This counts the three edges rather than adding their weights.'),('11','That is the cost4+5+2 of the upper safe route.'),('9','That is the cost4+1+3+1 throughDock2 andDock3.')],'The highlighted route has three edges, but its cost is the sum of their unequal weights.',kind='diagram',steps=['Read1→3 as2,3→5 as3,5→6 as1.','Add2+3+1=6.'],assumptions=['Traverse the named route from the marked start to the marked goal; weights share the same unspecified cost unit.'])
question(c,'Why cannot the apparent direct Dock1–Dock4 connection be used as a safe shortcut in the displayed graph?', [('Its red dashed styling denotes a blocked passage','The legend explicitly distinguishes blocked passages from safe ones.'),('Any path with two edges is forbidden','No such rule appears; blockage is the relevant constraint.'),('Dock4 is not a graph node','Dock4 is visibly labeled as a docking-station node.'),('The shortest-looking straight line always has the greatest weight','Geometric appearance does not establish the graph cost, and the passage is blocked regardless.')],'A depicted geometric connection need not be a permitted traversal edge.',kind='diagram',difficulty='easy',trap='Ignoring the legend and treating blocked connections as usable edges.')
# p115–116: operational search and source diagrams.
c=concept(115,'BFS frontier and optimality','FIFO layer exploration gives fewest edges, not least arbitrary weighted cost; uninformed means no goal heuristic.')
question(c,'Which combination describes BFS in the lecture?', [('FIFO queue; expand by edge-depth; minimize edge count','All three features are explicitly stated.'),('LIFO stack; expand one branch deeply; minimize arbitrary cost','This combines DFS mechanics with an unsupported cost guarantee.'),('Priority by Euclidean distance; minimize all path costs','A goal heuristic is not the stated BFS frontier rule.'),('FIFO queue; guarantee minimum sum of unequal edge weights','BFS’s edge-count guarantee does not automatically extend to unequal weights.')],'BFS is breadth-wise because older shallow frontier entries are processed first.',difficulty='easy',memory='Breadth first means queue first.')
question(c,'A route with2edges costs100, while another route with3edges costs3. Which guarantee does BFS provide under ordinary unweighted BFS?', [('It can choose the2edge route; its guarantee is about edge count','A depth2 goal is reached before depth3, despite the larger total weight.'),('It must choose cost3 because3<100','Ordinary BFS does not prioritize accumulated edge cost.'),('It compares the two costs before choosing a frontier node','That is not FIFO layer expansion.'),('It cannot search a graph that has weight labels','It can ignore weight labels, but then does not optimize them.')],'Choosing the correct optimization objective is separate from finding a path.',kind='scenario',assumptions=['Both paths lead to the same goal; standard BFS ignores weight labels and returns a minimum-edge path.'],trap='Using the word shortest without specifying whether it means edges or weighted cost.')
c=concept(115,'BFS source-graph trace','The illustrated unweighted graph has a4edge highlighted shortest path, potentially tied with others.')
question(c,'In printed slide21, the highlighted route is S→A→C→F→G. How many edges does it contain?', [('4','Five successive vertices are joined by four edges.'),('5','This counts vertices rather than traversed edges.'),('3','This omits one transition.'),('8','That is the length of the highlighted DFS route on the next slide.')],'Path length by edge count is one fewer than the number of vertices on this simple listed path.',kind='diagram',difficulty='easy')
question(c,'Run BFS on the slide21 undirected graph fromS toG. Discover neighbors alphabetically, mark visited on enqueue, and test for the goal on dequeue. What dequeue order occurs throughG?', [('S,A,B,C,D,E,F,H,G','FIFO layers areS; thenA,B; thenC,D,E; thenF,H; thenG.'),('S,A,C,F,D,B,E,H,G','This follows a deep recursive route rather than FIFO layers.'),('S,B,E,H,G','This skips earlier queued vertices and gives only one path.'),('S,A,B,C,F,G','This skipsD andE that were enqueued beforeF.')],'The queue preserves all shallower discovered vertices even when a promising branch exists.',kind='algorithm_trace',difficulty='hard',steps=['DequeueS; enqueueA,B.','DequeueA; enqueueC,D. DequeueB; enqueueE becauseD is already discovered.','DequeueC; enqueueF. DequeueD;F is already discovered. DequeueE; enqueueH.','DequeueF; enqueueG. DequeueH;G is already discovered. DequeueG and stop.'],assumptions=['Undirected edges:S-A,S-B,A-C,A-D,B-D,B-E,C-F,D-F,E-H,F-G,H-G.','Neighbors are visited in alphabetical order; visited-on-enqueue; goal test on dequeue; FIFO queue.'])
c=concept(116,'DFS frontier, backtracking and limits','LIFO/depth-first exploration backtracks after exhausting a branch and does not promise optimality.')
question(c,'When a depth-first exploration reaches a node with no unvisited continuation, what does it do?', [('Backtracks to a node with an unvisited child','This is the defining continuation strategy described on the slide.'),('Restarts all search from the initial node without remembering visits','That is not the stated DFS backtracking procedure.'),('Must immediately report that no solution exists anywhere','Other branches may remain unexplored.'),('Converts every edge weight to1 and runs BFS automatically','No automatic algorithm switch is part of DFS.')],'Depth first commits to a branch temporarily, not permanently.',kind='algorithm_trace',difficulty='easy',steps=['Follow an unvisited child while one exists.','If the branch is exhausted, return along the search stack.','Continue with another unvisited child.'])
question(c,'Which statement about the DFS path highlighted on printed slide22 is justified?', [('It is a first-found solution, not necessarily a minimum-edge path','The text explicitly warns against equating first-found with optimal.'),('It must be minimum-cost because the goal was found','Finding a goal does not establish cost optimality.'),('It must contain fewer edges than the highlighted BFS path','The displayed DFS route is longer, and no such guarantee exists.'),('Its LIFO frontier makes all path costs equal','A data structure does not alter edge weights.')],'The order of exploration can find a valid but longer route before a better one.',kind='diagram',difficulty='easy')
c=concept(116,'DFS source-graph trace','Under recursive alphabetical exploration, the source’s highlighted route visitsS,A,C,F,D,B,E,H,G.')
question(c,'On the same undirected graph, use recursive DFS, alphabetical neighbor order, a visited set, and stop immediately on enteringG. Which first solution path results?', [('S→A→C→F→D→B→E→H→G','Alphabetical choices produce the full deep highlighted route beforeG is reached.'),('S→A→C→F→G','AtF, unvisitedD precedesG alphabetically.'),('S→B→E→H→G','AtS, A precedesB.'),('S→A→D→F→G','AtA, C precedesD.')],'A deterministic neighbor-order convention is essential: DFS alone does not uniquely determine a path.',kind='algorithm_trace',difficulty='hard',steps=['S choosesA, thenA choosesC, thenC choosesF.','AtF skip visitedC, chooseD beforeG.','D skips visitedA, choosesB. B choosesE after skippingD.','E choosesH, thenH choosesG. Stop on enteringG.'],pages=[115],assumptions=['Undirected edges:S-A,S-B,A-C,A-D,B-D,B-E,C-F,D-F,E-H,F-G,H-G.','Recursive DFS with alphabetical unvisited-neighbor order; global visited set; goal test on entry.'])
question(c,'Compare the illustrated first DFS solution with the illustrated BFS solution, counting edges only. Which comparison is correct?', [('DFS has8edges; BFS has4edges','The listed routes contain9 and5 vertices respectively.'),('DFS has4edges; BFS has8edges','This reverses the counts.'),('Both must have4edges because they share endpoints','Shared endpoints do not force equal route lengths.'),('DFS has9edges; BFS has5edges','Those are vertex counts, not edge counts.')],'The figure is a direct counterexample to treating the first DFS solution as shortest.',kind='diagram',pages=[115],steps=['DFS:S,A,C,F,D,B,E,H,G has8transitions.','BFS:S,A,C,F,G has4transitions.'])
# p117–118: classification-tree structure, information gain and figure logic.
c=concept(117,'Decision-tree component roles','Internal nodes test attributes, branches encode outcomes and leaves give labels/actions.')
question(c,'Which mapping of classification-tree parts is correct?', [('Internal node=test; branch=test outcome; leaf=final decision','This matches all three roles described.'),('Internal node=final label; branch=test; leaf=outcome probability only','This exchanges the roles.'),('Every node must contain a final motor torque','The tree may encode questions and classifications, not only torques.'),('Branches represent graph-search queue positions','That is not the classification-tree interpretation given here.')],'Tests route an observation through outcomes until a decision is reached.',kind='match',difficulty='easy')
c=concept(117,'Decision tree versus random forest','A tree is one explicit rule set; a forest combines multiple trees for robustness.')
question(c,'What distinguishes a random forest from a single decision tree in this lecture?', [('It combines many decision trees for robustness','The slide states this as the key contrast.'),('It contains no decision rules','Its component trees still encode rules.'),('It is simply a deeper branch of one tree','The distinction is an ensemble of trees, not merely depth.'),('It is defined as a FIFO path-search queue','That is a BFS implementation detail, not a forest.')],'Combining several trees is different from adding tests to one tree.',kind='definition',difficulty='easy')
c=concept(118,'Information gain with child weighting','Choose the split maximizing parent entropy minus probability-weighted child entropy.')
question(c,'A parent has entropy1bit. A split makes children with weights0.25 and0.75 and entropies0 and0.8bits. What is its information gain?', [('0.4bits','Weighted child entropy is0.25×0+0.75×0.8=0.6; subtract from1.'),('0.6bits','That is the weighted remaining entropy, not its reduction.'),('0.2bits','This subtracts the unweighted sum0.8 from1.'),('1.8bits','This adds rather than subtracts child entropy.')],'Larger children contribute proportionally more to the average uncertainty left after the split.',kind='numerical',steps=['Expected child entropy=0.25(0)+0.75(0.8)=0.6bit.','Gain=1−0.6=0.4bit.'],formulas=[form('IG=H(parent)-sum_c P(c)H(c)',{'c':'child node','P(c)':'fraction routed to child','H':'entropy'},{'IG,H':'bits'})],trap='Dropping the child weights.')
question(c,'Two candidate attributes give information gains0.15 and0.35bits on the same node. Which is preferred by the stated rule?', [('The attribute with0.35bits gain','It removes more uncertainty.'),('The attribute with0.15bits gain','That leaves more uncertainty than the higher-gain split.'),('Always the first attribute in alphabetical order','That is not the stated selection rule.'),('The one with the largest remaining entropy regardless of gain','The aim is entropy reduction, not maximizing uncertainty left.')],'The chosen test should provide the largest reduction in uncertainty.',kind='scenario',difficulty='easy')
c=concept(118,'Grasp-force decision diagram','Glass leads to low force; non-glass thick to high force; non-glass thin to low force.')
question(c,'Using the displayed grasping tree, select every fully specified observation that leads to Low Force.', [('Glass surface, even if thick','The Yes branch reachesFragile thenLowForce before a thickness test.'),('Non-glass surface and thick','The No branch reachesThickness, andThick selectsHighForce.'),('Non-glass surface and thin','The No/Thin branch selectsLowForce.'),('No surface or thickness observation at all','The figure does not specify a default action for missing inputs.')],'Tree evaluation follows branches in order; a condition on a branch not visited is irrelevant.',correct=(0,2),kind='diagram',difficulty='hard',trap='Applying the thickness rule to a glass object even though the tree stops on the glass branch.')
question(c,'What makes the displayed grasping decision tree interpretable?', [('Its sequence of explicit tests and outcomes explains the selected force','The path can be traced from observed attributes to the action.'),('It has no intermediate conditions','It visibly contains surface and thickness tests.'),('Its output is chosen randomly after every observation','The figure shows deterministic rules for the listed inputs.'),('It guarantees every object is physically safe under every circumstance','The pedagogical rule does not establish such a universal engineering guarantee.')],'A person can trace why a particular low/high-force decision was reached.',kind='conceptual',difficulty='medium')
# p119–121: complexity, heuristic caution and completeness.
c=concept(119,'Asymptotic comparison','Highest-order growth provides a hardware-independent comparison; constants can matter for finite inputs.')
question(c,'Which growth classification matches the slide examples T_A=100n+1000 and T_B=n²+1?', [('A is linear O(n); B is quadratic O(n²)','Their dominant terms are proportional ton andn².'),('A is O(1000); B is O(1)','Constants do not dominate asn becomes large.'),('Both are quadratic because their values can exceedn² for some smalln','Finite values do not determine asymptotic degree.'),('A is logarithmic; B is linear','Neither dominant term has those forms.')],'Asymptotic classification discards constant multipliers and lower-order terms, not the leading power.',kind='definition',difficulty='easy')
question(c,'At n=10, which slide-example algorithm has fewer operations, and which has better asymptotic scaling?', [('B has fewer operations at10; A scales better asymptotically','A=2000 andB=101, but linear growth eventually beats quadratic growth.'),('A has fewer operations at10 and always at every n','A(10)=2000 is much larger thanB(10)=101.'),('B has fewer operations at10 and therefore must scale better asymptotically','A small-input comparison does not settle eventual growth.'),('They have equal operations at10','The displayed formulas give different values.')],'A worse growth rate can still win on small inputs because constants matter there.',kind='numerical',steps=['A(10)=100(10)+1000=2000.','B(10)=10²+1=101.','For large n, the n² term grows faster than the linear term.'],formulas=[form('T_A(n)=100n+1000; T_B(n)=n²+1',{'n':'input size','T_A,T_B':'operation counts'})],trap='Treating a Big-O comparison as a promise about all input sizes.')
question(c,'For the exact slide formulas and positive integer n, what is the smallest n for which A uses fewer operations than B?', [('110','At109,A=11900>B=11882; at110,A=12000<B=12101, and the quadratic difference increases thereafter.'),('100','At100,A=11000 andB=10001, soA is still slower.'),('109','At109,A exceedsB by18 operations.'),('1000','A does win there, but the first integer crossover occurs earlier.')],'Solve the actual inequality rather than inferring the crossover from asymptotic notation.',kind='numerical',difficulty='hard',steps=['A<B meansn²−100n−999>0.','The positive root is(100+sqrt(13996))/2, between109 and110.','The first positive integer above that root is110; direct substitution confirms it.'],formulas=[form('n²−100n−999>0',{'n':'positive integer input size'})])
c=concept(120,'Runtime cases and growth classes','Worst/average case are different summaries; logarithmic, linear and quadratic describe distinct growth rates.')
question(c,'For large n>1, what is the increasing order of the listed growth rates?', [('log n, n, n²','Logarithmic grows slower than linear, which grows slower than quadratic.'),('n², n, log n','This reverses the asymptotic order.'),('n, log n, n²','Logarithmic should precede linear.'),('All grow at the same rate after constants are removed','Their dependence onn remains different.')],'Removing constant factors does not make different functions ofn equivalent.',kind='sequence',difficulty='easy')
question(c,'Why should an algorithm report state whether its operation count is worst-case or average-case?', [('They summarize different sets of possible inputs and need not agree','Worst-case concerns the largest count in scope; average-case aggregates under an input distribution.'),('The labels change the robot’s physical coordinate system','They describe analysis, not geometry.'),('Average-case always equals worst-case for search','The slide lists distinct categories, not an equality.'),('Big-O notation automatically means an exact elapsed time on every computer','Asymptotic operation counts are not exact hardware timings.')],'A complexity statement is incomplete if the scenario it describes is ambiguous.',kind='conceptual')
c=concept(120,'Informed versus uninformed search','A* uses a heuristic, unlike BFS; the lecture’s universal efficiency wording needs qualification.')
question(c,'Which distinction between BFS and A* is directly supported without treating every efficiency claim as a universal guarantee?', [('A* uses a heuristic; ordinary BFS does not use a goal-location heuristic','This is the explicit methodological contrast.'),('A* always has a smaller Big-O class than BFS on every graph','The slide supplies no conditions that justify such a universal conclusion.'),('A* can never move temporarily away from the goal','Obstacles and path costs can require such movement; the simplified wording is not a general rule.'),('BFS optimizes every possible unequal-cost graph','BFS’s stated guarantee is minimum edge count.')],'The safe distinction is the information used to order search, not a blanket statement that one algorithm always does less work.',difficulty='hard',trap='Conflating a favorable practical example with a universal complexity guarantee.')
c=concept(121,'Completeness versus optimality','Finding a solution if one exists is different from finding the shortest one.')
question(c,'An algorithm is guaranteed to find some valid route whenever one exists in its stated problem class. What property does this establish by itself?', [('Completeness','It addresses finding a solution, as opposed to how good that solution is.'),('Optimality','A valid route could be longer or costlier than another.'),('Constant running time','The guarantee says nothing about the operation count.'),('Zero memory use','Search may still require substantial stored state.')],'Existence guarantees and quality guarantees are separate.',kind='definition',difficulty='easy')
c=concept(121,'Resolution completeness','Completeness can be conditional on sufficiently fine spatial discretization.')
question(c,'Which statement describes resolution completeness as presented?', [('The planner can find a solution when the discretization is fine enough','This is the slide’s grid-resolution qualification.'),('It finds every continuous-space solution on every coarse grid','A coarse grid may fail to represent a narrow feasible passage.'),('Its success probability must equal1 after exactly one random sample','This is neither the resolution criterion nor the probabilistic limit criterion.'),('It always finds the least-cost route regardless of representation','Resolution completeness alone is not an optimality guarantee.')],'A discretized map must be fine enough to represent the relevant route.',kind='scenario',difficulty='medium')
c=concept(121,'Probabilistic completeness','Success probability approaches1 with unbounded time; no fixed finite-time success or optimality guarantee follows.')
question(c,'Which statement expresses probabilistic completeness?', [('The probability of finding a solution tends to1 as time tends to infinity','This is the limit statement in the slide.'),('Every finite run is certain to find a solution','A limiting probability is not certainty at each finite time.'),('Every found path is necessarily the shortest','The property concerns finding a solution, not its optimality.'),('The probability of success decreases to0 with more time','This reverses the stated limit.')],'Asymptotic success probability does not supply a fixed deadline for guaranteed success.',kind='definition',difficulty='medium',trap='Reading an infinite-time limit as a finite-time promise.')
question(c,'What finite-step guarantee does the lecture explicitly deny for genetic-algorithm path planning?', [('Guaranteed discovery of the absolute shortest path','The slide says a near-optimal path may be found but no finite-step shortest-path guarantee is given.'),('The possibility of finding any useful path','The slide explicitly allows finding near-optimal paths.'),('The use of random mutations','Random mutations are cited as part of the method.'),('The possibility of a high-quality result quickly','The slide says this may happen, not that it is impossible.')],'A method may be useful and often effective without providing a finite-time optimality theorem.',kind='conceptual',assumptions=['This asks what the identified slide states; no universal probabilistic-completeness theorem for all genetic algorithms is assumed.'])
