# Executable author checks complement, but do not replace, independent source review.
import math
checks += [dict(id='vector_operations',passed=(tuple(2*a+b for a,b in zip((1,-2),(3,4)))==(5,0))),dict(id='norm',passed=(math.hypot(3,4)==5)),dict(id='bayes',passed=math.isclose(.8*.2/.4,.4)),dict(id='expected_reward',passed=math.isclose(.3*10+.7*(-2),1.6)),dict(id='binomial',passed=math.isclose(math.comb(3,2)*.8**2*.2,.384)),dict(id='information_gain',passed=math.isclose(1-(.25*0+.75*.8),.4)),dict(id='crossover',passed=(min(n for n in range(1,1001)if 100*n+1000<n*n+1)==110))]
edges=[('S','A'),('S','B'),('A','C'),('A','D'),('B','D'),('B','E'),('C','F'),('D','F'),('E','H'),('F','G'),('H','G')];adj=collections.defaultdict(list)
for a,b in edges:adj[a].append(b);adj[b].append(a)
for a in adj:adj[a].sort()
queue=collections.deque(['S']);seen={'S'};order=[]
while queue:
 u=queue.popleft();order.append(u)
 if u=='G':break
 for v in adj[u]:
  if v not in seen:seen.add(v);queue.append(v)
checks.append(dict(id='BFS_trace',passed=order==['S','A','B','C','D','E','F','H','G'],actual=order))
seen=set();route=[]
def dfs(u):
 seen.add(u);route.append(u)
 if u=='G':return True
 for v in adj[u]:
  if v not in seen and dfs(v):return True
 route.pop();return False
dfs('S');checks.append(dict(id='DFS_trace',passed=route==['S','A','C','F','D','B','E','H','G'],actual=route))
checks.append(dict(id='factory_routes',passed=(2+3+1==6 and 4+5+2==11 and 4+1+3+1==9)))
assert all(x['passed']for x in checks),checks
