# Human-readable spacing is part of the frozen question content.
import re
def readable(s):
 s=re.sub(r"([a-z])([A-Z])",r"\1 \2",s)
 s=re.sub(r"\b([A-Za-z]{2,})(?=\d)",r"\1 ",s)
 s=re.sub(r"\ba(?=\d)","a ",s)
